/** Element */
declare class Element {
  /**
   * Constant for Attribute Kind ( 'prim' )
   */
  static readonly AK_PRIM: string;

  /**
   * Constant for Attribute Kind ( 'enum' )
   */
  static readonly AK_ENUM: string;

  /**
   * Constant for Attribute Kind ( 'ref' )
   */
  static readonly AK_REF: string;

  /**
   * Constant for Attribute Kind ( 'refs' )
   */
  static readonly AK_REFS: string;

  /**
   * Constant for Attribute Kind ( 'obj' )
   */
  static readonly AK_OBJ: string;

  /**
   * Constant for Attribute Kind ( 'objs' )
   */
  static readonly AK_OBJS: string;

  /**
   * Constant for Attribute Kind ( 'var' )
   */
  static readonly AK_VAR: string;

  /**
   * Constant for Attribute Kind ( 'custom' )
   */
  static readonly AK_CUSTOM: string;

  /**
   * Return a super type of a given type.
   * @signature getSuperType(subType: constructor ): constructor
   */
  static getSuperType(subType: Constructor ): Constructor;

  /**
   * Return a generalized type of given elements.
   * @signature getCommonType(elems: Array < Element >): constructor
   */
  static getCommonType(elems: any[] ): Constructor;

  /**
   * Find an available name in a given array. (e.g. Class1, Class2, ... )
   * @signature getNewName(array: Array < Element >, prefix: string ): string
   */
  static getNewName(array: any[] , prefix: string ): string;

  /**
   * Merge values of a particular property of an array of elements If all values are same, then return the value. Otherwise, return null.
   * @signature mergeProps(elems: Array < Element >, prop: string )
   */
  static mergeProps(elems: any[] , prop: string ): any;

  /**
   * globaly unique identifier
   */
  _id: string;

  /**
   * reference to its parent
   */
  _parent: object;

  /**
   * Return class name for display (e.g. "Class" rather than "UMLClass").
   * @signature getDisplayClassName(): string
   */
  getDisplayClassName(): string;

  /**
   * Return Class. (equivalent to type[element.getClassName()])
   * @signature getClass(): constructor
   */
  getClass(): Constructor;

  /**
   * Return Class name.
   * @signature getClassName(): string
   */
  getClassName(): string;

  /**
   * Return Meta Class.
   * @signature getMetaClass(): Object
   */
  getMetaClass(): Record<string, any>;

  /**
   * Return Meta Attributes.
   * @signature getMetaAttributes(): Array <{name: string , kind: string , type: string }>
   */
  getMetaAttributes(): any[];

  /**
   * Return name of parent's field containing this object.
   * @signature getParentField(): string
   */
  getParentField(): string;

  /**
   * Return CSS class name of icon for this object. (Shown in Explorer)
   * @signature getNodeIcon(): string
   */
  getNodeIcon(): string;

  /**
   * Return textual string for this object. (Shown in Explorer)
   * @signature getNodeText(options: object ): string
   */
  getNodeText(options: object ): string;

  /**
   * Return ordering priority number. (Lower value comes first in Explorer)
   * @signature getOrdering(index: number ): Number
   */
  getOrdering(index: number ): Number;

  /**
   * Return all child nodes to be shown in Explorer.
   * @signature getChildNodes(sort: boolean ): Array < Element >
   */
  getChildNodes(sort: boolean ): any[];

  /**
   * Return all children.
   * @signature getChildren(): Array < Element >
   */
  getChildren(): any[];

  /**
   * Traverse all nodes in the tree structure. (Breadth-First Traversal)
   * @signature traverse(fun: function (elem: Element ))
   */
  traverse(...args: any[]): any;

  /**
   * Traverse all nodes in the tree structure. (Depth-First Traversal)
   * @signature traverseDepthFirst(fun: function (elem: Element ))
   */
  traverseDepthFirst(...args: any[]): any;

  /**
   * Traverse a specific field chains. (Breadth-First Traversal)
   * @signature traverseField(field: string , fun: function )
   */
  traverseField(field: string , fun: (...args: any[]) => any ): any;

  /**
   * Traverse a specific field chains. (Depth-First Traversal)
   * @signature traverseFieldDepthFirst(field: string , fun: function )
   */
  traverseFieldDepthFirst(field: string , fun: (...args: any[]) => any ): any;

  /**
   * Traverse up along with the _parent chain.
   * @signature traverseUp(fun: function )
   */
  traverseUp(fun: (...args: any[]) => any ): any;

  /**
   * Find an element by name. Find through ownedElements chain, and then lookup through _parent chain.
   * @signature lookup(name: string , typeFilter: constructor , namespace: Element ): Element
   */
  lookup(name: string , typeFilter: Constructor , namespace: Element ): Element;

  /**
   * Find by name in child elements
   * @signature findByName(name: ( string | Array < string >)): Element
   */
  findByName(name: ( string | any[] )): Element;

  /**
   * Look down an element along parent-children chains.
   * @signature lookdown(pathName: Array < string >): Element
   */
  lookdown(pathName: any[] ): Element;

  /**
   * Return true only if a given elem is one of the container.
   * @signature isOneOfTheContainers(elem: Element ): boolean
   */
  isOneOfTheContainers(elem: Element ): boolean;

  /**
   * Return true only if it can contain the kind of elements
   * @signature canContainKind(kind: string ): Boolean
   */
  canContainKind(kind: string ): Boolean;

  /**
   * Return true only if it can contain a given element.
   * @signature canContain(elem: Element ): Boolean
   */
  canContain(elem: Element ): Boolean;

  /**
   * Return true only if it could be copied.
   * @signature canCopy(): Boolean
   */
  canCopy(): Boolean;

  /**
   * Return true only if it could be deleted alone.
   * @signature canDelete(): Boolean
   */
  canDelete(): Boolean;

  /**
   * Return true only if it could be hidden without deletion.
   * @signature canHide(): Boolean
   */
  canHide(): Boolean;

  /**
   * Return true only if it can accomodate elements in clipboard based on a given kind and copyContext.
   * @signature canPaste(kind: string , copyContext: {field: string }): Boolean
   */
  canPaste(...args: any[]): any;
}

